  function automatic logic [15:0] swap16(input logic [15:0] x, input int sel);
    case (sel)
      0: swap16 = {x[5], x[12], x[14], x[13], x[9], x[3], x[6], x[4], x[8], x[1], x[15], x[11], x[0], x[7], x[10], x[2]};
      1: swap16 = {x[14], x[3], x[8], x[12], x[13], x[7], x[15], x[4], x[6], x[2], x[9], x[5], x[11], x[0], x[1], x[10]};
      2: swap16 = {x[15], x[7], x[6], x[14], x[13], x[12], x[5], x[4], x[3], x[2], x[11], x[10], x[9], x[1], x[0], x[8]};
      default: swap16 = x;
    endcase
  endfunction

  // the middle result's part of the second network's key
  function automatic logic [95:0] kmid(input logic [15:0] m);
    kmid = 96'd0;
    kmid[1] = kmid[1] ^ m[0];
    kmid[10] = kmid[10] ^ m[1];
    kmid[44] = kmid[44] ^ m[2];
    kmid[68] = kmid[68] ^ m[3];
