  always_ff @(posedge clk) begin
    st <= {st[2:0], go};
    if (go) begin
      logic [15:0] s;
      logic [7:0]  aa, bb;
      s = swap16(counter, 0);
      bb = s[15:8];
      aa = s[7:0] ^ f1_r0(bb, k1[23:0]);
      bb = bb ^ f1_r1(aa, k1[47:24]);
      a <= aa; b <= bb; d_q <= data;
