    if (st[0]) begin
      logic [7:0] aa, bb;
      aa = a ^ f1_r2(b, k1[71:48]);
      bb = b ^ f1_r3(aa, k1[95:72]);
      k2 <= k2b ^ kmid({bb, aa});
      begin
        logic [15:0] s;
        s = swap16(d_q, 1);
        b <= s[15:8]; a <= s[7:0];
      end
    end
    if (st[1]) begin
      logic [7:0] aa, bb;
      aa = a ^ f2_r0(b, k2[23:0]);
      bb = b ^ f2_r1(aa, k2[47:24]);
